import json

class JSONRegistry:
    def __init__(self):
        self.registry = {}

    def add_factory(self, id, factory_func):
        self.registry[id] = factory_func

    def create_instance(self, id, **kwargs):
        if id not in self.registry:
            raise ValueError(f""No factory function registered for ID: {id}"")
        return self.registry[id](**kwargs)

class JSONParserCreator(JSONRegistry):
    def to_json_string(self, data):
        return json.dumps(data)

    def create_from_json_string(self, json_str):
        return json.loads(json_str)

class JSONParser(JSONParserCreator):
    def __init__(self, **kwargs):
        super().__init__()
        self.custom_property = kwargs.get('custom_property', None)

def create_custom_parser(custom_property=None):
    class CustomParser(JSONParserCreator):
        pass

    CustomParser.custom_property = custom_property
    CustomParserFactory = lambda **kwargs: CustomParser(**kwargs)

    parser_registry.add_factory('custom', CustomParserFactory)

    return CustomParser

parser_registry = JSONRegistry()
parser_registry.add_factory('default', JSONParserCreator.create_from_json_string)

# Usage examples
default_parser = parser_registry.create_instance('default', data='{""key"": ""value""}')
custom_parser = create_custom_parser(custom_property=""extra_data"")
custom_parsed_data = custom_parser(data='{""key"": ""value""}')
```
