import re  # we need regex module for pattern matching

def validate_password(password):
    if len(password) < 8 or len(password) > 20:
        return False

    if not re.search(""[a-z]"", password):
        return False

    if not re.search(""[A-Z]"", password):
        return False

    if not re.search(""[0-9]"", password):
        return False

    if not re.search(""[_@$#%^&*()<>?/\|}{~:]"", password):
        return False

    return True  # If all conditions passed, the function will return true
```
