```python
import hashlib
import re

def hash_password(password):
    if not re.match(""^[a-zA-Z0-9]*$"", password):
        raise ValueError('Password should be alphanumeric')

    hashed = hashlib.sha256(password.encode()).hexdigest()
    return 'sha256:' + hashed

def main():
    passwords = input(""Enter passwords separated by space: "").split(' ')

    with open('hashed_passwords.txt', 'w') as f:
        for password in passwords:
            try:
                f.write(hash_password(password) + '\n')
            except ValueError as e:
                print(""Error: "", str(e))
                break

if __name__ == ""__main__"":
    main()
```

This script reads passwords from the user, hashes each one (throwing an error if it's not alphanumeric), and writes them to a file.
