import csv
from ffi import from_buffer, CData

class Graph:
    def __init__(self):
        self.vertices = {}

    def addVertex(self, vertex):
        if vertex not in self.vertices:
            self.vertices[vertex] = []

    def addEdge(self, source, destination, weight=1):
        if source in self.vertices and destination in self.vertices:
            self.vertices[source].append((destination, weight))

    def checkEdge(self, source, destination):
        return any(destination == d for _, d in self.vertices[source])

def readGraphFromCSV(filename):
    graph = Graph()

    with open(filename) as file:
        reader = csv.reader(file)

        for row in reader:
            source, destination, weight = int(row[0]), int(row[1]), float(row[2])

            graph.addVertex(source)
            graph.addVertex(destination)
            graph.addEdge(source, destination, weight)

    return graph
