import hashlib
import re

def validate_password(password):
    if not re.match(""^(?=.*[a-zA-Z])(?=.*\d)[a-zA-Z\d]{8,}$"", password):
        raise ValueError(""Password must be alphanumeric and at least 8 characters long."")

def hash_password(password):
    hashed_password = hashlib.sha256(password.encode()).hexdigest()
    return f""sha256:{hashed_password}""

def process_passwords(passwords):
    hashed_list = []
    for password in passwords:
        try:
            validate_password(password)
            hashed_list.append(hash_password(password))
        except ValueError as e:
            print(f""Error: {e}"")
    return hashed_list

def save_to_file(hashed_list, filename=""hashed_pass.txt""):
    with open(filename, ""w"") as file:
        for hashed in hashed_list:
            file.write(hashed + ""\n"")

# Main program starts here
if __name__ == ""__main__"":
    passwords = [""Password1"", ""SecureP@ss"", ""12345678"", ""ComplexPass!""]

    try:
        hashed = process_passwords(passwords)
        save_to_file(hashed)
        print(""Hashing completed successfully."")
    except Exception as e:
        print(f""An error occurred: {e}"")
