class DataProcessor(private val connectionString: String) {
    private val reader = BufferedReader(InputStreamReader(System.`in`))

    /**
     * Reads integers from standard input and returns them as an array.
     */
    fun readIntegers(): IntArray {
        print(""Enter integers separated by spaces: "")
        val input = reader.readLine()!!
        return input.split(' ').map { 
            it.toIntOrNull() ?: throw IllegalArgumentException(""Invalid integer value provided."")
        }.toIntArray()
    }

    /**
     * Sends byte array to a database server, using JDBC, and returns a ResultSet object.
     * @param byteArray Byte array to be sent to the database server.
     * @return ResultSet object containing the data returned by the database server.
     */
    fun queryDatabase(byteArray: ByteArray): ResultSet {
        DriverManager.getConnection(connectionString).use { connection ->
            val preparedStatement = connection.prepareCall(""{call YourProcedureName(?)}"")
            preparedStatement.setBytes(1, byteArray)

            return preparedStatement.executeQuery()
        }
    }
}

fun main() {
