def fib_sum_even(max_value):
    seq = [0, 1]
    while True:
        new_num = seq[-2] + seq[-1]
        if new_num > max_value:
            break
        else:
            seq.append(new_num)

    sum_even = sum([i for i in seq if not i % 2])
    return (seq, sum_even)
