```python
import os
from cryptography.hazmat.primitives import serialization as crypto_serialization
from cryptography.hazmat.primitives.asymmetric import rsa
from cryptography.hazmat.backends import default_backend as crypto_default_backend
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import padding
import base64
import binascii
from pyasn1.type import univ, namedtype
from pyasn1.codec.der import encoder

class CRC_INDICATION_REL8_TAG(univ.Sequence):
    componentType = namedtype.NamedTypes(
        namedtype.NamedType('crcflags', univ.Integer())
    )

class RX_UE_INFORMATION_TAG(univ.Sequence):
    componentType = namedtype.NamedTypes(
        namedtype.NamedType('ueinfo', univ.OctetString()),
        namedtype.NamedType('rnti', univ.Integer())
    )

class NFAPI_CRC_INDICATION_PDU_T(univ.Sequence):
    componentType = namedtype.NamedTypes(
