```python
from kubernetes import client, config
import jsonschema
import time
import logging
from datetime import datetime

# Load the KubeConfig file 
config.load_kube_config()

v1 = client.CoreV1Api()
apps_v1 = client.AppsV1Api()

def validate_app_configuration(config):
    schema = {
        ""type"": ""object"",
        ""properties"": {
            ""image_name"": {""type"": ""string""},
            ""container_ports"": {""type"": ""array""},
            ""resource_limits"": {""type"": ""object""}
        },
        ""required"": [""image_name""]
    }

    try:
        jsonschema.validate(config, schema)
    except jsonschema.exceptions.ValidationError as e:
        logging.error(""Invalid app configuration: {}"".format(e))
        return False

    return True

def deploy_app(apps):
    for app in apps:
        if not validate_app_configuration(app):
            continue

        body = {
            ""apiVersion"": ""v1"",
            ""kind"": ""Pod"",
            ""metadata"": {
                ""name"": app['image_name']
            },
            ""spec"": {
                ""containers"": [{
                    ""name"": app['image_name'],
                    ""image"": app['image_name'],
                    ""ports"": app.get('container_ports', []),
                    ""resources"": app.get('resource_limits', {})
                }]
            }
        }

        try:
            response = apps_v1.create_namespaced_deployment(body=body, namespace=""default"")
            logging.info(""Deployed application: {}"".format(app['image_name']))
        except Exception as e:
            logging.error(""Failed to deploy application {}: {}"".format(app['image_name'], str(e)))

        # Rate limit - replace with actual mechanism for your use case
        time.sleep(1)
```
