    def __init__(self):
        self._cache = {}

    @staticmethod
    def _generate_user_agent():
        template = random.choice(WebPageGenerator.USER_AGENT_TEMPLATES)
        version = str(random.randint(1, 99)) + ""."" + str(random.randint(0, 9)) + ""."" + str(random.randint(0, 99)) + ""."" + str(random.randint(0, 99))
        random_int = str(random.randint(1, 537))
        return template.format(version=version, random_int=random_int)

    @staticmethod
    def _generate_url():
        return random.choice(WebPageGenerator.URL_FORMATS) + ""/"" + str(random.randint(1, 99))

    @staticmethod
    def _check_availability(url):
        try:
            response = requests.get(""https://isitarealemail.com/api/email"", params={""email"": url})
            if response.status_code == 200 and json.loads(response.text)[""status""] == ""available"":
                return True
        except Exception as e:
            logging.error(""Exception occurred while checking availability of URL"", exc_info=e)
        return False

    def generate(self, total=100, min_page_rank=1, max_page_rank=10):
        generated = []
        for _ in range(total):
            url = self._generate_url()
            while not self._check_availability(url):
                url = self._generate_url()
            content_type = random.choice(WebPageGenerator.CONTENT_TYPES)
            last_accessed = int(datetime.now().timestamp())
            page_rank = random.randint(min_page_rank, max_page_rank)
            user_agent = self._generate_user_agent()
            generated.append({""URL"": url, ""content type"": content_type, ""last accessed timestamp"": last_accessed, ""page rank"": page_rank, ""user agent"": user_agent})
        return generated

    def cache(self, pages):
        for page in pages:
            self._cache[page[""URL""]] = page

# Instance usage example
