        self.flag = bool(random.getrandbits(1))

def generate_objects(size):
    try:
        if size < 1:
            raise ValueError(""Size should be greater than 0."")

        objects = []
        for _ in range(size):
            obj = CustomObject()

            # error handling for object initialization
            if not all([hasattr(obj, 'num'), hasattr(obj, 'str_num'), hasattr(obj, 'flag')]):
                raise RuntimeError(""Some objects were not properly initialized."")

            objects.append(obj)
        return objects

    except ValueError as ve:
        print('Value Error: ', ve)
        return []

    except Exception as e:
        print('Unexpected error: ', e)
        return []

def print_objects(objects):
