        print(f""Object {i+1}:"")
        print(""Number: "", obj.num)
        print(""String Representation: "", obj.str_num)
        print(""Flag: "", obj.flag)
        print()

def find_maximum(objects):
    try:
        max_value = max([obj.num for obj in objects])
        print('Max value is :', max_value)

    except ValueError as ve:
        print(""Can't determine maximum value because list is empty."")

    except Exception as e:
        print(""An unexpected error occurred."", e)

# Usage
