    return array

def print_array(array: List[CustomObject]):
    if not array:
        sys.exit(""Array is empty."")

    for i, obj in enumerate(array):
        print(f""Element {i+1}: Integer={obj.integer}, String='{obj.string}', Flag={str(obj.flag)}"")

def find_maximum(array: List[CustomObject]) -> int:
    if not array:
        sys.exit(""Array is empty."")

    return max([obj.integer for obj in array])
```

