import random
import json

class WeatherForecastGenerator:
    def __init__(self):
        self.date_pool = list(range(1, 366))   # Assuming non-leap years
        self.forecasts = []

    def generate_forecasts(self, count, seed):
        if count > len(self.date_pool):
            raise ValueError(""Requested count exceeds available unique dates."")

        random.seed(seed)
        self.forecasts = random.sample(self.date_pool, count)

        # Memory management
        del self.date_pool

        return self.verify_distinctness()

    def verify_distinctness(self):
        if len(set(self.forecasts)) == len(self.forecasts):
            return True
        else:
            raise ValueError(""Duplicate date values found in the generated forecasts."")

def check_generator(generator_class):
    try:
        generator = generator_class()
        forecasts = generator.generate_forecasts(100, 42)

        if forecasts:
            print(""Generated forecasts:"", json.dumps(forecasts))
            print(""Distinctness verification:"", generator.verify_distinctness())

    except ValueError as e:
        print(e)

# Example usage
